    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int R = grid.size(), C = grid[0].size();
        vector<vector<int>> g = grid;
        for (const auto& h : hits) g[h[0]][h[1]]--;
        int total = R * C, roof = total;
        parent.resize(total + 1);
        iota(parent.begin(), parent.end(), 0);
        sz.assign(total + 1, 1);
        for (int c = 0; c < C; c++) if (g[0][c] == 1) unite(c, roof);
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (g[r][c] == 1) {
                    int idx = r * C + c;
                    if (r + 1 < R && g[r + 1][c] == 1) unite(idx, (r + 1) * C + c);
                    if (c + 1 < C && g[r][c + 1] == 1) unite(idx, r * C + c + 1);
                }
            }
        }
        vector<int> ans;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int i = (int)hits.size() - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            g[r][c]++;
            if (g[r][c] != 1) { ans.push_back(0); continue; }
            int prev = sz[find(roof)];
            int idx = r * C + c;
            if (r == 0) unite(idx, roof);
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && g[nr][nc] == 1) {
                    unite(idx, nr * C + nc);
                }
            }
            int cur = sz[find(roof)];
            if (find(idx) == find(roof)) ans.push_back(max(0, cur - prev - 1));
            else ans.push_back(0);
        }
        reverse(ans.begin(), ans.end());
        return ans;
    }
};

class Solution {
    private int[] parent, sz;
    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) {
            parent[rx] = ry;
            sz[ry] += sz[rx];
        }
    }
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int R = grid.length, C = grid[0].length;
        int[][] g = new int[R][C];
        for (int r = 0; r < R; r++) System.arraycopy(grid[r], 0, g[r], 0, C);
        for (int[] h : hits) g[h[0]][h[1]]--;
        int total = R * C, roof = total;
        parent = new int[total + 1];
        sz = new int[total + 1];
        for (int i = 0; i <= total; i++) { parent[i] = i; sz[i] = 1; }
        for (int c = 0; c < C; c++) if (g[0][c] == 1) union(c, roof);
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (g[r][c] == 1) {
                    int idx = r * C + c;
                    if (r + 1 < R && g[r + 1][c] == 1) union(idx, (r + 1) * C + c);
                    if (c + 1 < C && g[r][c + 1] == 1) union(idx, r * C + c + 1);
                }
            }
        }
        int[] ans = new int[hits.length];
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0], c = hits[i][1];
            g[r][c]++;
            if (g[r][c] != 1) { ans[i] = 0; continue; }
            int prev = sz[find(roof)];
            int idx = r * C + c;
            if (r == 0) union(idx, roof);
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && g[nr][nc] == 1) {
                    union(idx, nr * C + nc);
                }
            }
            int cur = sz[find(roof)];
            ans[i] = (find(idx) == find(roof)) ? Math.max(0, cur - prev - 1) : 0;
        }
        return ans;
    }
}

var hitBricks = function(grid, hits) {
    const R = grid.length, C = grid[0].length;
    const g = grid.map(row => row.slice());
    for (const [r, c] of hits) g[r][c]--;
    const total = R * C, roof = total;
    const parent = Array.from({ length: total + 1 }, (_, i) => i);
    const sz = new Array(total + 1).fill(1);
    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx !== ry) {
            parent[rx] = ry;
            sz[ry] += sz[rx];
        }
    }
    for (let c = 0; c < C; c++) if (g[0][c] === 1) union(c, roof);
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (g[r][c] === 1) {
                const idx = r * C + c;
                if (r + 1 < R && g[r + 1][c] === 1) union(idx, (r + 1) * C + c);
                if (c + 1 < C && g[r][c + 1] === 1) union(idx, r * C + c + 1);
            }
        }
    }
    const ans = new Array(hits.length).fill(0);
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (let i = hits.length - 1; i >= 0; i--) {
        const [r, c] = hits[i];
        g[r][c]++;
        if (g[r][c] !== 1) continue;
        const prev = sz[find(roof)];
        const idx = r * C + c;
        if (r === 0) union(idx, roof);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && g[nr][nc] === 1) {
                union(idx, nr * C + nc);
            }
        }
        const cur = sz[find(roof)];
        ans[i] = (find(idx) === find(roof)) ? Math.max(0, cur - prev - 1) : 0;
    }
    return ans;
};
